package pay;

import static readcode.Assert.*;

import java.time.Duration;
import java.time.Instant;

public class PaymentServiceTest {
    private ManualClock clock;
    private CircuitBreaker breaker;
    private PaymentService service;
    private boolean gatewayDown;
    private int gatewayCalls;

    public void setUp() {
        clock = new ManualClock(Instant.parse("2026-11-19T12:00:00Z"));
        breaker = new CircuitBreaker(3, Duration.ofSeconds(30), clock);
        gatewayDown = false;
        gatewayCalls = 0;
        Gateway gateway = (token, cents) -> {
            gatewayCalls++;
            if (gatewayDown) {
                throw new GatewayException("503 from gateway");
            }
            return "ch_" + gatewayCalls;
        };
        service = new PaymentService(gateway, breaker);
    }

    private void failOnce() {
        gatewayDown = true;
        service.charge("tok", 1000);
        gatewayDown = false;
    }

    public void testHealthyChargeIsApproved() {
        PaymentService.Result r = service.charge("tok", 1000);
        assertEquals(PaymentService.Status.APPROVED, r.status());
        assertEquals(CircuitBreaker.State.CLOSED, breaker.state());
    }

    public void testOpensAfterThreeConsecutiveFailures() {
        failOnce();
        failOnce();
        assertEquals(CircuitBreaker.State.CLOSED, breaker.state(), "two failures should not trip a threshold of 3");
        failOnce();
        assertEquals(CircuitBreaker.State.OPEN, breaker.state());
    }

    public void testOpenCircuitRejectsWithoutCallingGateway() {
        failOnce();
        failOnce();
        failOnce();
        int before = gatewayCalls;
        PaymentService.Result r = service.charge("tok", 1000);
        assertEquals(PaymentService.Status.REJECTED_CIRCUIT_OPEN, r.status());
        assertEquals(before, gatewayCalls, "gateway must not be called while open");
    }

    public void testSuccessInBetweenKeepsFailuresFromAccumulating() {
        failOnce();
        failOnce();
        service.charge("tok", 1000);
        failOnce();
        failOnce();
        System.out.println("state after fail, fail, success, fail, fail: " + breaker.state());
        assertEquals(CircuitBreaker.State.CLOSED, breaker.state(), "failures separated by a success are not consecutive");
    }

    public void testProbeSuccessClosesAndNeedsFullThresholdToReopen() {
        failOnce();
        failOnce();
        failOnce();
        clock.advance(Duration.ofSeconds(31));
        assertEquals(PaymentService.Status.APPROVED, service.charge("tok", 1000).status());
        assertEquals(CircuitBreaker.State.CLOSED, breaker.state());
        failOnce();
        assertEquals(CircuitBreaker.State.CLOSED, breaker.state(), "one failure after recovery must not re-open the circuit");
    }

    public void testFailedProbeReopensForAnotherWindow() {
        failOnce();
        failOnce();
        failOnce();
        clock.advance(Duration.ofSeconds(31));
        failOnce();
        assertEquals(CircuitBreaker.State.OPEN, breaker.state());
        assertEquals(PaymentService.Status.REJECTED_CIRCUIT_OPEN, service.charge("tok", 1000).status());
    }

    public void testOnlyOneProbeWhileHalfOpen() {
        failOnce();
        failOnce();
        failOnce();
        clock.advance(Duration.ofSeconds(31));
        assertTrue(breaker.tryAcquire(), "first caller after the window is the probe");
        assertFalse(breaker.tryAcquire(), "second caller must be rejected while the probe is in flight");
    }
}
